!function(e){function n(n){for(var t,m,o=n[0],p=n[1],c=n[2],s=0,u=[];s<o.length;s++)m=o[s],Object.prototype.hasOwnProperty.call(a,m)&&a[m]&&u.push(a[m][0]),a[m]=0;for(t in p)Object.prototype.hasOwnProperty.call(p,t)&&(e[t]=p[t]);for(d&&d(n);u.length;)u.shift()();return i.push.apply(i,c||[]),r()}function r(){for(var e,n=0;n<i.length;n++){for(var r,m=i[n],o=!0,p=1;p<m.length;p++)r=m[p],0!==a[r]&&(o=!1);o&&(i.splice(n--,1),e=t(t.s=m[0]))}return e}function t(n){if(m[n])return m[n].exports;var r=m[n]={i:n,l:!1,exports:{}};return e[n].call(r.exports,r,r.exports,t),r.l=!0,r.exports}var m={},a={30:0},i=[];t.m=e,t.c=m,t.d=function(e,n,r){t.o(e,n)||Object.defineProperty(e,n,{enumerable:!0,get:r})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,n){if(1&n&&(e=t(e)),8&n)return e;if(4&n&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(t.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&n&&"string"!=typeof e)for(var m in e)t.d(r,m,function(n){return e[n]}.bind(null,m));return r},t.n=function(e){var n=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(n,"a",n),n},t.o=function(e,n){return Object.prototype.hasOwnProperty.call(e,n)},t.p="";var o=window.webpackJsonp=window.webpackJsonp||[],p=o.push.bind(o);o.push=n,o=o.slice();for(var c=0;c<o.length;c++)n(o[c]);var d=p;i.push([206,0]),r()}({206:function(e,n,r){"use strict";r.r(n);var t=r(0);Object(t.a)("de","army",r(207),r(1))},207:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"火炮","link":"de_army#de_army_cannon"}],"model":"105mm K18型加农炮","description":"<p>加农炮与榴弹炮都是属于压制敌方火力用的重炮，主要作陆军师、团级的中远程火力支援；加农炮特点是初速大，弹道低直，射角小（最大射角为45°），适合对装甲目标或者远距离目标进行直接射击，而榴弹炮的特点则是初速小、弹道弯曲，射角大（射角可以达到70°），适合对一些隐蔽目标（含反斜面目标）或大面积目标进行射击。</p><p>从外形看，加农炮身管长，通常为口径的40倍以上，105mm K18型加农炮的炮管长度就有5.46米长，为52倍口径；榴弹炮身管则较短, 通常为口径的20—30倍，如105mm Ie FH18型榴弹炮的炮管长度只有2.94米，为28倍口径。</p><p>二战期间，德军装备的加农炮口径主要有105mm、150mm和170mm等多种，其中105mm K18型加农炮是德军炮兵部队早期装备的一种远程火力支援火炮，主要配备给师属炮兵部队，也有用作海防炮等其它用；但德军中这型炮装备的数量并不多，原因是该炮的产量不高，如1941年生产了45门，而1942年更少，只生产了25门，该炮大部分都随德陆军部队投入东线作战。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_cannon105K18_11.jpg","description":"<h6>105mm K18型加农炮</h6><p>（注：一些资料为了与105mm榴弹炮作区别，称之为100mm K18火炮）</p><p>技术数据：</p><p>火炮口径：105mm；</p><p>炮管长：5.46米（52倍口径）；</p><p>火炮重：战斗5.642吨，运输6.434吨；</p><p>火炮射界（水平方向）：60度，火炮射角（垂直方向）：45度；</p><p>射速：6发/分钟；</p><p>最大射程：19075米。</p>","caption":""}],"part2title":"战场上的105mm K18型加农炮","part2description":"","part2content":[{"image":"imgs/de/army/de_army_cannon105K18_21.jpg","description":"在一个德军的加农炮阵地中，一门105mm K18加农炮的炮组成员正摆着姿势拍照，其中多名炮兵拿着弹丸，中间的两个炮兵拿着夯锤。而最左边带着袖带的应是指挥官。将105mm K18加农炮与105mm Ie FH18榴弹炮区别开的最可靠方法是看炮管，K18加农炮的炮管更长，更细，此外还要注意炮管上方换热器油缸上的字母“C”。","caption":""},{"image":"imgs/de/army/de_army_cannon105K18_22.jpg","description":"各就各位作出准备射击状的一门105mm K18加农炮炮组成员，从左到右，我们看到第一人拿着弹药盒，第二个拿着夯锤，第三个拿着弹丸，而炮手则操纵着手轮，射手则站在他拉绳子射击时的位置，戴着耳机的炮兵上方的人应是该炮的指挥官。","caption":""},{"image":"imgs/de/army/de_army_cannon105K18_23.jpg","description":"二战期间，架设在在法国大西洋沿岸的一门105mm K18加农炮。由于加农炮初速大,射程远,弹道低伸, 适宜于直接瞄准射击海上活动目标, 因此也会被当作海防炮用。","caption":""},{"image":"imgs/de/army/de_army_cannon105K18_24.jpg","description":"东线苏联战场，由于在开阔的地形上难以找到掩护物，该门105mm K18加农炮的炮组成员为他们的炮披上了掩护网罩。注意，该炮阵地已完成构筑，火炮大架岔腿处伸出的大条尖钉应是作为定位用。","caption":""},{"image":"imgs/de/army/de_army_cannon105K18_25.jpg","description":"被牵引运输中的一门105mm K18加农炮。请注意，该炮轮毂上的橡胶轮胎是专用于机动车牵引的。运输时，炮管是通过支腿上的U形槽轨道放置在车架上的，照片的右侧地上放着火炮的大地锹。","caption":""},{"image":"imgs/de/army/de_army_cannon105K18_26.jpg","description":"二战期间德军在波兰波兹南市（Poznań）举行的一次仪式，讲台两侧摆放着105mm K18加农炮。请注意，该炮的炮管特别细长，这是加农炮的外形特点。","caption":""},{"image":"imgs/de/army/de_army_cannon105K18_27.jpg","description":"西线法国战场，战役结束后德军炮兵部队正在转移。多辆Sd.Kfz 6装甲牵引车拖带着105mm K18加农炮停在公路上。请注意，Sd.Kfz 6装甲车牵引力为5吨，而105mm K18加农炮运输重为6吨多，牵引力不足会影响炮兵部队的机动性。","caption":""},{"image":"imgs/de/army/de_army_cannon105K18_28.jpg","description":"德军的Sd.Kfz 7半履带装甲车正牵引着105mm K18加农炮在草原上行驶。为了克服Sd.Kfz 6装甲车牵引力不足的缺点，德军改用牵引力为8吨的Sd.Kfz 7半履带装甲车来牵引6吨多重的105mm K18加农炮。由于重型半履带装甲车牵引力大，炮组全部成员又都能坐在车上，因此大大提高了炮兵部队的机动能力。","caption":""},{"image":"imgs/de/army/de_army_cannon105K18_29.jpg","description":"这应是一张演习时摆拍的照片，几个炮兵跪立在一门105mm K18加农炮作出准备射击姿态。","caption":""},{"image":"imgs/de/army/de_army_cannon105K18_30.jpg","description":"一门被美军俘获的105mm K18加农炮，美军正将其绑在一辆美式2.5吨的CCKW-353战术卡车上，以便从野外撤离。请注意，炮管是向后伸出并锁定的，从而减小了炮管的总长度和倾斜度，而炮的锄铲则与牵引车相连接。","caption":""}]}')}});